import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { G1_BASE, G2_BASE, g1FromBytes, g1ToBytes, g2FromBytes, g2ToBytes, gtEql, gtPow, hashToG1 } from '../bls';
import { bls12_381 } from '@noble/curves/bls12-381';
import { fameDecrypt, fameEncrypt, fameKeygen, fameSetup, hAttr, hCol, type G1x3, type G2x3 } from '../fame';
import { normalizePolicy } from '../policy';

/**
 * Differential tests against an INDEPENDENT implementation. The fixture was generated by py_ecc 8.0.0 (pure Python,
 * different code base from @noble/curves) via test-oracle/gen_vectors_fame.py, which builds its own span program,
 * recomputes the keys and ciphertext of the FAME scheme, and DECRYPTS by Gaussian elimination before emitting.
 * Here the same scalars drive this package's code and every point must match byte for byte; the package must also
 * decrypt the Python ciphertext with the Python key (and the reverse).
 */
interface Case {
  name: string;
  policy: unknown;
  attrs: string[];
  scalars: { a: string[]; b: string[]; d: string[]; r: string[]; sigma: string[]; sigmaPrime: string; s: string[] };
  h: string[]; mskg: string[]; k0: string[]; kp: string[]; key: Record<string, string[]>; ct0: string[]; rows: string[][];
}
const V = JSON.parse(readFileSync(join(__dirname, 'vectors', 'fame-pyecc.json'), 'utf8')) as { dst: string; cases: Case[] };
const big = (h: string) => BigInt('0x' + h);
const hex = (u: Uint8Array) => Buffer.from(u).toString('hex');
const g1 = (h: string) => {
  const p = g1FromBytes(Buffer.from(h, 'hex'));
  if (p === null) throw new Error('fixture G1 point rejected');
  return p;
};
const g2 = (h: string) => {
  const p = g2FromBytes(Buffer.from(h, 'hex'));
  if (p === null) throw new Error('fixture G2 point rejected');
  return p;
};
const tri1 = (a: string[]) => a.map(g1) as G1x3;
const tri2 = (a: string[]) => a.map(g2) as G2x3;
const x1 = (p: G1x3) => p.map((q) => hex(g1ToBytes(q)));
const x2 = (p: G2x3) => p.map((q) => hex(g2ToBytes(q)));

describe('FAME key and ciphertext components agree with py_ecc', () => {
  it('has the expected reference cases', () => {
    expect(V.cases.map((c) => c.name)).toEqual(['single', 'and2', 'or2', '2of3', '3of5', 'nested']);
    expect(V.dst).toBe('ATLAS-PCA-ABE:FAME:H-G1:SHA256-SSWU-RO:v1');
  });

  for (const c of V.cases) {
    const sc = c.scalars;
    const tree = (() => {
      const n = normalizePolicy(c.policy);
      if (!n.ok) throw new Error(n.reason);
      return n.tree;
    })();
    const { mpk, msk } = fameSetup([big(sc.a[0]!), big(sc.a[1]!)], [big(sc.b[0]!), big(sc.b[1]!)], [big(sc.d[0]!), big(sc.d[1]!), big(sc.d[2]!)]);
    const key = fameKeygen(msk, c.attrs, [big(sc.r[0]!), big(sc.r[1]!)], sc.sigma.map(big), big(sc.sigmaPrime));
    const enc = fameEncrypt(mpk, tree, [big(sc.s[0]!), big(sc.s[1]!)]);

    it(`${c.name}: master, user key and ciphertext points are byte-identical`, () => {
      expect([hex(g2ToBytes(mpk.h1)), hex(g2ToBytes(mpk.h2))]).toEqual(c.h);
      expect(x1(msk.g)).toEqual(c.mskg);
      expect(x2(key.k0)).toEqual(c.k0);
      expect(x1(key.kp)).toEqual(c.kp);
      expect(Object.fromEntries([...key.attrs].map(([k, v]) => [k, x1(v)]))).toEqual(c.key);
      expect(x2(enc.ct.ct0)).toEqual(c.ct0);
      expect(enc.ct.rows.map(x1)).toEqual(c.rows);
    });

    it(`${c.name}: decrypts the reference ciphertext with the reference key to the same KEM key`, () => {
      const refKey = { k0: tri2(c.k0), kp: tri1(c.kp), attrs: new Map(Object.entries(c.key).map(([k, v]) => [k, tri1(v)])) };
      const k = fameDecrypt(refKey, tree, { ct0: tri2(c.ct0), rows: c.rows.map(tri1) });
      expect(k).not.toBeNull();
      expect(gtEql(k!, enc.k)).toBe(true);
    });
  }

  it('the oracles hash with the documented, injective encoding', () => {
    expect(hex(g1ToBytes(hAttr('a', 1, 0)))).not.toBe(hex(g1ToBytes(hAttr('a', 0, 1))));
    expect(hex(g1ToBytes(hAttr('a', 0, 0)))).not.toBe(hex(g1ToBytes(hCol(0, 0, 0))));
    expect(hex(g1ToBytes(hAttr('', 0, 0)))).not.toBe(hex(g1ToBytes(hCol(0, 0, 0))));
    expect(hex(g1ToBytes(hAttr('ab', 0, 0)))).toBe(hex(g1ToBytes(hashToG1(Buffer.concat([Buffer.from([1, 0, 0, 0, 2]), Buffer.from('ab'), Buffer.from([0, 0])])))));
  });

  it('group generators and the GT exponent agree with a direct pairing identity', () => {
    const a = 5n;
    const lhs = bls12_381.pairing(G1_BASE.multiply(a), G2_BASE, true);
    expect(gtEql(lhs, gtPow(bls12_381.pairing(G1_BASE, G2_BASE, true), a))).toBe(true);
  });
});
